"""Q16 round 2: rewrite the Q16 entries of /output/report.json (idempotent; replaces the round-1 Q16 results/recipe/dataset/caveat/interpretation paragraph; keeps the round-1 s71 forward-model entry). Usage: python3 -I s86_update_report_q16r2.py"""
import json
